def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.25)
        return max(0.0, float(bid))

    opp_prev_bids = []
    cindy_prev = None
    desperate_count = 0
    rich_alive = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_alive += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            opp_prev_bids.append(float(pbid))
        if oid == 'Cindy' and pbid is not None:
            cindy_prev = float(pbid)

    highest_prev = max(opp_prev_bids) if opp_prev_bids else 0.0
    avg_prev = sum(opp_prev_bids) / len(opp_prev_bids) if opp_prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    if cindy_prev is None:
        cindy_prev = highest_prev

    if urgency >= 5:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif urgency >= 3:
        if scarcity >= 1:
            target = max(DAILY_SALARY * 0.72, min(cindy_prev * 0.78, DAILY_SALARY * 1.02))
        else:
            target = max(DAILY_SALARY * 0.52, avg_prev + 3.0)
    else:
        if scarcity == 2:
            target = max(DAILY_SALARY * 0.58, min(cindy_prev * 0.68, DAILY_SALARY * 0.92))
        elif scarcity == 1:
            target = max(DAILY_SALARY * 0.42, min(avg_prev + 1.5, DAILY_SALARY * 0.7))
        else:
            target = DAILY_SALARY * 0.22

    if desperate_count >= 2 and urgency < 5:
        target += 6.0
    if rich_alive <= 1 and urgency <= 1:
        target -= 4.0
    if supply >= 23 and urgency <= 2:
        target -= 5.0

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget / max(1, reserve_days)
    if urgency <= 1:
        target = min(target, soft_cap * 0.9 + DAILY_SALARY * 0.15)
    elif urgency <= 3:
        target = min(target, soft_cap * 1.2 + DAILY_SALARY * 0.2)

    min_safe = 0.0
    if urgency >= 5:
        min_safe = DAILY_SALARY * 0.8
    elif urgency >= 3:
        min_safe = DAILY_SALARY * 0.5

    bid = max(min_safe, target)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure: if someone bid very high yesterday, they likely continue.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Convert supply into a rough "urgency" proxy: more supply => easier to win without extreme bids.
    # Use integer-safe indexing by mapping to bins.
    # supply in [15,25] => 3 bins
    bin_idx = int((supply - MIN_SUPPLY) / ((MAX_SUPPLY - MIN_SUPPLY) / 3.0))
    if bin_idx < 0:
        bin_idx = 0
    if bin_idx > 2:
        bin_idx = 2

    # Base bid target: moderate, then adjust for my hp/no-water.
    # These targets aim to beat Cindy (high bidder) only when my situation is critical.
    base_targets = [DAILY_SALARY * 0.45, DAILY_SALARY * 0.55, DAILY_SALARY * 0.65]
    target = float(base_targets[bin_idx])

    # If highest opponent bid was huge, they likely value survival; avoid full contest unless needed.
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        # Only escalate if I'm in danger.
        if my_hp <= 2 or my_no_water_days >= 2:
            target = DAILY_SALARY * 0.9
        else:
            target = min(target, DAILY_SALARY * 0.6)

    # If I am already near death, bid aggressively.
    if my_hp <= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp <= 4:
        target = max(target, DAILY_SALARY * 0.65)

    # If I've gone multiple days without water, increase urgency.
    if my_no_water_days >= 3:
        target = max(target, DAILY_SALARY * 0.8)
    elif my_no_water_days == 2:
        target = max(target, DAILY_SALARY * 0.65)

    # Budget cap
    if my_budget <= 0:
        return 0.0

    bid = min(my_budget, target)

    # Small rationalization: if supply is low end, slightly more to secure allocation.
    if supply <= (MIN_SUPPLY + 2):
        bid = min(my_budget, bid + DAILY_SALARY * 0.05)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    cindy = opponents_status.get('Cindy', {})
    cindy_bid = cindy.get('previous_trace', {}).get('bid', 0) if cindy else 0

    # If supply is tight, bid to beat Cindy's average, otherwise conserve budget
    if supply < 18:
        bid = max(cindy_bid * 1.1, DAILY_SALARY * 0.6)
    else:
        bid = max(cindy_bid * 0.8, DAILY_SALARY * 0.3)

    # Desperation mode
    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)

    return float(min(my_status['budget'], bid))
